#!/usr/bin/env bash
# Pushes the Kiosk Process live-progress fix. Two separate things had to
# change to actually fix the "timing is buggy" complaint, not just one:
#
#  1. ADMIN PANEL (takes effect immediately, this script restarts it):
#     - app/blueprints/instances.py
#         GET .../kiosk/status long-polls (?wait=<s>&sig=<sig>) instead of
#         a flat interval, and now also reports pending_command.queued_at
#         (epoch ms) so the browser can render a real elapsed-time-based
#         progress bar instead of a static "queued" message.
#     - app/templates/instances/detail.html
#         Status pill now shows "Starting…/Stopping…/Restarting…
#         /Configuring…" (accent color) the instant a command is queued,
#         with an animated progress bar + percentage underneath, driven by
#         the elapsed time since queued_at against a rough per-command-type
#         estimate — capped short of 100% until the state actually
#         changes, so it never lies about being done.
#
#  2. AGENT (only takes effect on machines running the updated Agent -
#     see the notes this script prints at the end):
#     - agent/commands.py
#         This was the ACTUAL root cause of "the timing is buggy": the
#         status pill only ever updated on the Agent's own scheduled
#         heartbeat (heartbeat_interval_seconds, 60s default) - completely
#         decoupled from the command ack, which lands in ~1-2s. Clicking
#         Start would show "success" in Recent Commands almost instantly
#         while the status pill sat on the OLD value for up to a minute.
#         Fixed by firing an immediate heartbeat right after a
#         start/stop/restart/configure command executes (success or
#         failure), so the real status lands within a couple of seconds
#         instead of up to 60s. Also rebuilds
#         app/static/installers/opslab-agent.tar.gz with this fix so
#         future installs get it automatically.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app agent requirements.txt run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS"
cp app/blueprints/instances.py "backups/$TS/instances.py.bak" 2>/dev/null || true
cp app/templates/instances/detail.html "backups/$TS/detail.html.bak" 2>/dev/null || true
cp agent/commands.py "backups/$TS/commands.py.bak" 2>/dev/null || true
cp app/static/installers/opslab-agent.tar.gz "backups/$TS/opslab-agent.tar.gz.bak" 2>/dev/null || true
echo "==> Backed up existing files to backups/$TS/"

echo "==> Writing app/blueprints/instances.py"
base64 -d > app/blueprints/instances.py << 'INSTANCES_PY_B64'

INSTANCES_PY_B64

echo "==> Writing app/templates/instances/detail.html"
base64 -d > app/templates/instances/detail.html << 'DETAIL_HTML_B64'

DETAIL_HTML_B64

echo "==> Writing agent/commands.py (source of truth in this repo)"
base64 -d > agent/commands.py << 'AGENT_COMMANDS_PY_B64'

AGENT_COMMANDS_PY_B64

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz (for future installs)"
base64 -d > app/static/installers/opslab-agent.tar.gz << 'AGENT_TAR_B64'

AGENT_TAR_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/blueprints/instances.py').read())"
echo "    app/blueprints/instances.py: syntax OK"
python3 -c "import ast; ast.parse(open('agent/commands.py').read())"
echo "    agent/commands.py: syntax OK"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null
echo "    served agent tarball is readable"

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
source venv/bin/activate
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "Admin Panel side is live now:"
echo "  - Status pill shows Starting/Stopping/Restarting/Configuring with"
echo "    an animated % while a command is in flight, and updates within"
echo "    about a second of the actual state changing (no page reload)."
echo ""
echo "IMPORTANT - the Agent side needs a manual follow-up on machines"
echo "that are ALREADY enrolled with an older Agent:"
echo "  - This script only rewrote the served installer tarball for"
echo "    *future* installs. There is no remote Agent self-update channel"
echo "    yet, so already-enrolled kiosks won't get the immediate-"
echo "    heartbeat fix until you reinstall the Agent on them (re-run"
echo "    install.sh / install.ps1, which pulls the tarball this script"
echo "    just rewrote)."
echo "  - Until that reinstall happens on a given kiosk, its status pill"
echo "    will still lag up to heartbeat_interval_seconds (60s default)"
echo "    behind reality on that machine specifically — the progress bar"
echo "    will still animate and look busy, it'll just take longer than"
echo "    the ~2-6s it'll take once that kiosk is on the updated Agent."
echo "==================================================================="
